python3 - <<'PY'
import re
for file in ['db/schema.rb','db/schema_sqlite.rb','saas/db/saas_schema.rb']:
    print('\n---',file,'---')
    s=open(file).read()
    tables=[]
    for m in re.finditer(r'create_table "([^"]+)"[^\n]* do \|t\|(.*?)(?=\n  end)',s,re.S):
        name, body=m.groups()
        cols=[]
        for line in body.splitlines():
            x=re.search(r'\bt\.\w+ "([^"]+)"(.*)',line)
            if x:
                col,rest=x.groups()
                cols.append(col + (' [nullable]' if 'null: false' not in rest else ''))
        if 'account_id' not in [c.split()[0] for c in cols]:
            tables.append((name,cols))
    for name,cols in tables:
        print(name+': '+', '.join(cols))
PY

