ruby - <<'RUBY'
def add_fixture_account(path, accounts)
  text = File.read(path)
  blocks = text.split(/(?=^[^\s#_][^:\n]*:\s*$)/)
  updated = blocks.map do |block|
    name = block[/\A([^\s#_][^:\n]*):\s*$/, 1]
    next block unless name && accounts.key?(name)
    next block if block.match?(/^\s+account:/)

    "#{block.rstrip}\n  account: #{accounts.fetch(name)}\n\n"
  end.join
  File.write(path, updated)
end

