def tables(path)
  File.read(path).scan(/  create_table "([^"]+)"[^\n]* do \|t\|(.*?)\n  end/m).to_h
end
sqlite, mysql = ARGV.map { |path| tables(path) }
issues = []
sqlite.each do |table, body|
  next unless body.lines.any? { |line| line.include?('"account_id"') }
  column = body.lines.find { |line| line.include?('"account_id"') }
  next unless mysql_body = mysql[table]
  mysql_column = mysql_body.lines.find { |line| line.include?('"account_id"') }
  sqlite_simple = body.lines.any? { |line| line =~ /t\.index \["account_id"\]/ }
  mysql_simple = mysql_body.lines.any? { |line| line =~ /t\.index \["account_id"\]/ }
  issues << "#{table}: SQLite account_id is nullable or unindexed" unless column.include?("null: false") && sqlite_simple
  issues << "#{table}: MySQL account_id is nullable or unindexed" unless mysql_column&.include?("null: false") && mysql_simple
end
puts issues.empty? ? "SQLite and MySQL snapshots: all shared account_id columns are required and indexed" : issues.join("\n")
missing_mysql = sqlite.keys.select { |table| tables('db/schema_sqlite.rb')[table]&.include?('"account_id"') && !mysql.key?(table) && table != 'search_records' }
puts "Missing tenant tables in MySQL dump: #{missing_mysql.join(', ')}" if missing_mysql.any?
RUBY

